const form=document.querySelector('#tradeinForm');if(form){const faq=document.createElement('section');faq.className='faq';faq.innerHTML='<p>ANTES DE EMPEZAR</p><h2>Claro y sin vueltas.</h2><details open><summary>¿Qué equipos toman?</summary><span>Evaluamos iPhone y otros smartphones según modelo, estado, batería y funcionamiento.</span></details><details><summary>¿Cuánto demora?</summary><span>Respondemos en hasta 15 minutos dentro del horario de atención.</span></details><details><summary>¿Cómo envío las fotos?</summary><span>Adjuntalas en el formulario y te contactamos por WhatsApp o email.</span></details>';form.parentNode.insertBefore(faq,form);form.addEventListener('submit',async(event)=>{event.preventDefault();const status=document.querySelector('#tradeinStatus'),data=new FormData(form),files=[...form.querySelector('input[type=file]').files],names=[];status.textContent='Enviando tu solicitud…';try{for(const file of files){const safe=`${Date.now()}-${file.name.replace(/[^a-z0-9._-]/gi,'-')}`;const upload=await fetch(`${SUPABASE_URL}/storage/v1/object/tradein-photos/${safe}`,{method:'POST',headers:{apikey:SUPABASE_KEY,Authorization:`Bearer ${SUPABASE_KEY}`,'Content-Type':file.type||'application/octet-stream','x-upsert':'false'},body:file});if(!upload.ok)throw new Error('upload');names.push(safe)}const response=await fetch(`${SUPABASE_URL}/rest/v1/tradein_requests`,{method:'POST',headers:{apikey:SUPABASE_KEY,Authorization:`Bearer ${SUPABASE_KEY}`,'Content-Type':'application/json',Prefer:'return=minimal'},body:JSON.stringify({model:data.get('model'),capacity:data.get('capacity'),condition:data.get('condition'),battery:data.get('battery'),customer_name:data.get('name'),contact:data.get('contact'),notes:data.get('notes'),photo_names:names,status:'new'})});if(!response.ok)throw new Error('request');form.reset();status.textContent='Solicitud recibida. Revisaremos tu equipo y te responderemos dentro de 15 minutos.'}catch(error){status.textContent='No pudimos enviar la solicitud. Revisá tu conexión e intentá nuevamente.'}});}
